sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float start;
uniform float end;
uniform float angle;
uniform float feather;
uniform float softness;
half4 main(float2 coord) {
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a));
    float ext = abs(size.x * d.x) + abs(size.y * d.y);
    float x = dot(coord - size * 0.5, d) + ext * 0.5;
    float w = max(feather, 1.0);
    float m = clamp((x - start * ext) / w + 0.5, 0.0, 1.0) * clamp((end * ext - x) / w + 0.5, 0.0, 1.0);
    if (softness > 0.0) {
        float soft = softness * 0.01 * ext;
        m = smoothstep(start * ext - soft, start * ext, x) * (1.0 - smoothstep(end * ext, end * ext + soft, x));
    }
    return image.eval(coord) * half(m);
}
